#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    // Input Fahrenheit degree from stdin
    double fahrenheit = 0.0;
    if (!(std::cin >> fahrenheit)) {
        return 0;
    }

    // Correct floating-point division using 5.0 / 9
    double celsius = (5.0 / 9.0) * (fahrenheit - 32.0);

    // Demonstrating CheckPoint expressions
    int intDiv = 25 / 4;       // 6
    double floatDiv = 25 / 4.0; // 6.25
    double powerResult = std::pow(2.0, 3.5); // 2^3.5

    std::cout << std::fixed << std::setprecision(4);
    std::cout << "Fahrenheit " << fahrenheit << " is " << celsius << " in Celsius\n";
    std::cout << "25 / 4 = " << intDiv << "\n";
    std::cout << "25 / 4.0 = " << floatDiv << "\n";
    std::cout << "pow(2.0, 3.5) = " << powerResult << "\n";

    return 0;
}

#include <iostream>

int main() {
    // Fixed epoch timestamp provided via stdin for deterministic output testing
    // Example: 1203183086 seconds (from textbook trace)
    long long totalSeconds = 0;
    if (!(std::cin >> totalSeconds)) {
        return 0;
    }

    // 1. Compute current second in the minute
    int currentSecond = static_cast<int>(totalSeconds % 60);

    // 2. Compute total minutes and current minute in the hour
    long long totalMinutes = totalSeconds / 60;
    int currentMinute = static_cast<int>(totalMinutes % 60);

    // 3. Compute total hours and current hour in the day (GMT)
    long long totalHours = totalMinutes / 60;
    int currentHour = static_cast<int>(totalHours % 24);

    // Display current time in GMT format
    std::cout << "Current time is " << currentHour << ":"
              << currentMinute << ":" << currentSecond << " GMT\n";

    return 0;
}
